create or replace function public.svc_qilt_register_evidence(p_source_id uuid,p_source_url text,p_storage_path text,p_content_hash text,p_survey_code text,p_collection_version integer,p_worker_version text) returns uuid language plpgsql security definer set search_path to 'pipeline','public','extensions' as $function$ declare v_id uuid; begin select id into v_id from pipeline.evidence_artifacts where source_id=p_source_id and evidence_type='qilt_source_workbook' and content_hash=p_content_hash order by captured_at desc limit 1; if v_id is null then insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata) values(p_source_id,'qilt_source_workbook',p_source_url,p_storage_path,p_content_hash,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'worker_version',p_worker_version,'source_container','official_qilt_zip','identity_authority',false)) returning id into v_id; end if; return v_id; end $function$; revoke all on function public.svc_qilt_register_evidence(uuid,text,text,text,text,integer,text) from public,anon,authenticated; grant execute on function public.svc_qilt_register_evidence(uuid,text,text,text,text,integer,text) to service_role;
